ROW_PARSER_MAP_RETURN_METHODS.push ('parseCurrencies');
ROW_PARSER_MAP_RETURN_METHODS.forEach ((m) => { J92J7_MAP_RETURN_METHODS.push (m); JAVA_MAP_RETURN_METHODS.add (m); });
