    'ArrayCacheBySymbolById': ARRAYCACHE_TYPE, 'ArrayCacheBySymbolBySide': ARRAYCACHE_TYPE,
    'OrderBook': ORDERBOOK_TYPE, 'OrderBookSide': ORDERBOOKSIDE_TYPE,
