    'testWatchTicker': [2],
    'testWatchTrades': [2],
    'transfer': [0, 2, 3],
    'transferBetweenMainAndSubAccount': [0],
    'transferBetweenSubAccounts': [0],
    'transferClassic': [0],
    'transferIn': [0],
    'transferOut': [0],
    'transferUta': [0],
    'unWatchFundingRate': [0],
    'unWatchMarkPrice': [0],
    'unWatchOHLCV': [0],
    'unWatchOrderBook': [0],
    'unWatchTicker': [0],
    'unWatchTrades': [0],
    'updateSpotCurrencyCode': [0],
    'verifyGiftCode': [0],
    'watchFundingRate': [0],
    'watchLiquidations': [0],
    'watchMarkPrice': [0],
    'watchMyLiquidations': [0],
    'watchOHLCV': [0],
    'watchOrderBook': [0],
    'watchTicker': [0],
    'watchTrades': [0],
    'withdraw': [0, 2],
    'withdrawRequest': [0],
    'withdrawWs': [0],
    'handleMarginModeAndParams': [0],
    'signEvmTransaction': [1],
    'createSubAccount': [0],
