    'buildOHLCVC': [ 1 ],
    'fetchContractOHLCV': [ 1 ],
    'fetchDerivativesOpenInterestHistory': [ 1 ],
    'fetch2': [ 2 ],
    'fetchIndexOHLCV': [ 1 ],
    'fetchMarkOHLCV': [ 1 ],
    'fetchOHLCV': [ 1 ],
    'fetchOHLCVRequest': [ 1 ],
    'fetchOHLCVWs': [ 1 ],
    'fetchOpenInterestHistory': [ 1 ],
    'fetchOptionOHLCV': [ 1 ],
    'fetchPremiumIndexOHLCV': [ 1 ],
    'fetchSpotOHLCV': [ 1 ],
    'fetchUTAOHLCV': [ 1 ],
    'parseOHLCVs': [ 2 ],
    'parseTradingViewOHLCV': [ 2 ],
    'parseWsOHLCVs': [ 2 ],
    'sign': [ 2 ],
    'unWatchOHLCV': [ 1 ],
    'watchOHLCV': [ 1 ],
